import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for required imports
found_requests = False
found_bs = False
found_json = False

for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'requests' for name in node.names):
        found_requests = True
    if isinstance(node, ast.ImportFrom) and node.module == 'bs4':
        for name in node.names:
            if name.name == 'BeautifulSoup':
                found_bs = True
    if isinstance(node, ast.Import) and any(name.name == 'json' for name in node.names):
        found_json = True

if not found_requests:
    raise AssertionError('Task 1: Missing import requests')
if not found_bs:
    raise AssertionError('Task 1: Missing from bs4 import BeautifulSoup')
if not found_json:
    raise AssertionError('Task 1: Missing import json')

# Check for requests.get() call
found_get = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
        if isinstance(node.func.value, ast.Name) and node.func.value.id == 'requests' and node.func.attr == 'get':
            found_get = True

if not found_get:
    raise AssertionError('Task 3: Missing requests.get() call')

# Check for raise_for_status()
found_raise = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'raise_for_status':
        found_raise = True

if not found_raise:
    raise AssertionError('Task 3: Missing response.raise_for_status()')

# Check for BeautifulSoup() call
found_soup = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'BeautifulSoup':
        found_soup = True

if not found_soup:
    raise AssertionError('Task 4: Missing BeautifulSoup() call')

# Check for find_all with class_
found_find_all = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'find_all':
        for kw in node.keywords:
            if kw.arg == 'class_':
                found_find_all = True

if not found_find_all:
    raise AssertionError('Task 5: Missing class_ parameter in find_all()')

# Check for for loop
found_loop = False
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        found_loop = True

if not found_loop:
    raise AssertionError('Task 7: Missing for loop')

# Check for dictionary creation with correct keys
found_dict = False
for node in ast.walk(tree):
    if isinstance(node, ast.Dict):
        keys = [ast.unparse(k) for k in node.keys]
        if all(key in str(keys) for key in ['quote', 'author', 'tags']):
            found_dict = True

if not found_dict:
    raise AssertionError('Task 8: Dictionary missing required keys (quote, author, tags)')

# Check for json.dump() call
found_json_dump = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'dump':
        found_json_dump = True

if not found_json_dump:
    raise AssertionError('Task 9: Missing json.dump() call')

# Check for with open statement
found_with = False
for node in ast.walk(tree):
    if isinstance(node, ast.With):
        found_with = True

if not found_with:
    raise AssertionError('Task 9: Missing with open() statement')

print('TEST_PASSED')
